int 
dtb_palette_exit_msg_initialize(DtbMessageData instance)
{
    char	*tmp_txt;
    if (instance->initialized)
    {
        return 0;
    }
    instance->initialized = True;

    instance->type = XmDIALOG_WARNING;
    instance->title = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 6, 1, "Application Builder"));
    instance->message = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 6, 161, "You have unsaved edits. Exiting App Builder\nwill discard your changes. Please confirm."));
    instance->action1_label = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 6, 3, "Discard Changes"));
    instance->action1_callback = (XtCallbackProc) NULL;
    instance->action2_label = (XmString) NULL;
    instance->action2_callback = (XtCallbackProc) NULL;
    instance->action3_label = (XmString) NULL;
    instance->action3_callback = (XtCallbackProc) NULL;
    instance->cancel_button = True;
    instance->cancel_callback = (XtCallbackProc) NULL;
    instance->help_button = True;
    tmp_txt = CATGETS(Dtb_project_catd, 6, 151, "Changes, which have not been saved, have been\nmade to the currently loaded project. If you\nexit App Builder, those changes will be lost.\nYou have the option of continuing with the exit\noperation or cancelling it.");
    instance->help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
    strcpy(instance->help_data.help_text, tmp_txt);
    
    instance->help_data.help_volume = "";
    instance->help_data.help_locationID = "";
    instance->default_button = DTB_CANCEL_BUTTON;
    return 0;
}

