static int 
dtb_palette_ab_palette_main_create(
    DtbPaletteAbPaletteMainInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    String	icon_name_str = NULL;
    String	title_str = NULL;
    static DtbObjectHelpDataRec	help_data = {
        "",
        "AppBuilder",
        "ABMainWindow",
    };
    char *tmp_txt;
    
    if (instance->ab_palette_main == NULL) {
        icon_name_str = XtNewString(CATGETS(Dtb_project_catd, 6, 135, "dtbuilder"));
        title_str = XtNewString(CATGETS(Dtb_project_catd, 6, 1, "Application Builder"));
        instance->ab_palette_main =
            XtVaCreatePopupShell("ab_palette_main",
                topLevelShellWidgetClass,
                parent,
                XmNallowShellResize, True,
                XmNtitle, title_str,
                XmNiconName, icon_name_str,
                XmNinitialState, NormalState,
                XmNmwmDecorations, MWM_DECOR_ALL | MWM_DECOR_RESIZEH,
                XmNmwmFunctions, MWM_FUNC_ALL | MWM_FUNC_RESIZE,
                NULL);
        XtFree(title_str);
        title_str = NULL;
        XtFree(icon_name_str);
        icon_name_str = NULL;
    }
    if (instance->ab_palette_main == NULL)
        return -1;

    if (instance->ab_palette_main_mainwin == NULL) {
        instance->ab_palette_main_mainwin =
            XtVaCreateWidget("dtb_palette_ab_palette_main_mainwin",
                xmMainWindowWidgetClass,
                instance->ab_palette_main,
                NULL);
        /*
         * Add help callback
         */
        tmp_txt = CATGETS(Dtb_project_catd, 6, 120, "The Main Window is the starting point for building a graphical user interface.  The interface is created by dragging objects from the App Builder object palette, editing the properties of interface objects, and adjusting the layout of the interface.");
        help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
        strcpy(help_data.help_text,tmp_txt);
        
        XtAddCallback(instance->ab_palette_main_mainwin,
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    if (instance->ab_palette_main_mainwin == NULL)
        return -1;

    if (instance->ab_palette_main_form == NULL) {
        instance->ab_palette_main_form =
            XtVaCreateWidget("ab_palette_main_form",
                xmFormWidgetClass,
                instance->ab_palette_main_mainwin,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_ANY,
                NULL);
    }
    if (instance->ab_palette_main_form == NULL)
        return -1;

    return 0;
}



